INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 32, 'theory', 'Quiz: the database in the application');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 0, 'What is the "N plus one" problem and how is it cured?', '["Lack of memory; increase the cache", "One query for a list and one query per item; cured by eager loading (a join, or a query with a list of identifiers)", "A connection error; restart the application", "A table lock; finish the transactions"]', 1, 'The log shows the same query template repeated dozens of times; one query instead of N cuts latency by orders of magnitude.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 1, 'Why is a pool that is too large harmful?', '["Nothing bad, the bigger the faster", "It takes up client memory", "The database server efficiently runs only as many queries as it has resources; the rest compete for them, and the pool hides the problem", "It is forbidden by the protocol"]', 2, 'Little''s law: the number of simultaneous requests = arrival rate × average time; the size is chosen by measurement.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 2, 'What makes an operation idempotent when the client retries?', '["Increasing the timeout", "Forbidding retries on the client side", "Turning off transactions", "An idempotency key: the result is stored with the key in one transaction, and on a retry the previous one is returned"]', 3, 'Networks are unreliable and clients retry; a retry must not double a charge or an order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 3, 'What is the "outbox" pattern for?', '["So the event is written to a table in the same transaction as the business change and then reliably published by a separate process", "To speed up reads", "To encrypt data", "To reduce the number of indexes"]', 0, 'This way you can''t get a change without an event or an event without a change; at-least-once delivery requires idempotent consumers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 32, 4, 'How do you avoid reading stale data from a replica right after a user''s write?', '["Never write", "Always read from the replica", "Read your own writes from the primary for a short time after the change, or pin the session to the primary", "Turn off replication"]', 2, 'A replica lags; reads critical for correctness go to the primary, and routing is done explicitly.');
